const reservarLeadsParaFunil = `-- name: ReservarLeadsParaFunil :many
UPDATE atendimento.leads
SET funil_status = 'enviando', funil_tentativas = funil_tentativas + 1, funil_proxima_em = now()
WHERE id IN (
    SELECT l.id FROM atendimento.leads l
    WHERE l.funil_status IN ('pendente', 'erro')
      AND l.funil_tentativas < 5
      AND l.funil_proxima_em <= now()
    ORDER BY l.id
    LIMIT $1
    FOR UPDATE SKIP LOCKED
)
RETURNING id
`

func (q *Queries) ReservarLeadsParaFunil(ctx context.Context, limite int32) ([]int64, error) {
	rows, err := q.db.Query(ctx, reservarLeadsParaFunil, limite)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reservarMensagensDeAtendimento = `-- name: ReservarMensagensDeAtendimento :many

WITH alvo AS (
    SELECT m.id
    FROM atendimento.mensagens m
    JOIN atendimento.conversas c ON c.id = m.conversa_id
    JOIN atendimento.bots b ON b.id = c.bot_id
    WHERE m.status = 'pendente'
      AND m.proxima_tentativa_em <= now()
      AND b.ativo
      AND b.slug = ANY($1::text[])
      -- Conversa que uma pessoa assumiu não entrega resposta de bot (issue #128). Assumir já
      -- cancela o que estava na fila; isto fecha a corrida de a resposta ter sido composta no
      -- mesmo instante em que o consultor escreveu.
      AND c.assumida_em IS NULL
    ORDER BY m.proxima_tentativa_em, m.id
    FOR UPDATE OF m SKIP LOCKED
    LIMIT $2
)
UPDATE atendimento.mensagens m
SET tentativas           = m.tentativas + 1,
    proxima_tentativa_em = now() + interval '2 minutes'
WHERE m.id IN (SELECT id FROM alvo)
RETURNING m.id, m.texto, m.tentativas,
          (SELECT c.telefone FROM atendimento.conversas c WHERE c.id = m.conversa_id)   AS telefone,
          (SELECT b.slug FROM atendimento.bots b
             JOIN atendimento.conversas c ON c.bot_id = b.id
            WHERE c.id = m.conversa_id)                                                 AS bot_slug,
          (SELECT c.id FROM atendimento.conversas c WHERE c.id = m.conversa_id)          AS conversa_id
`

type ReservarMensagensDeAtendimentoParams struct {
	Slugs  []string
	Limite int32
}

type ReservarMensagensDeAtendimentoRow struct {
	ID         int64
	Texto      string
	Tentativas int32
	Telefone   string
	BotSlug    string
	ConversaID int64
}

// Etapa D (o worker de WhatsApp). A fila de envio vive aqui, e não no worker: ele não tem papel
// no Postgres e não sabe o que é ensaio, teto ou bot desligado — só transporta.
// Reserva as próximas mensagens de um conjunto de bots. `FOR UPDATE SKIP LOCKED` + trava de 2
// minutos no `proxima_tentativa_em`: se o worker morrer entre a reserva e o envio, a mensagem
// volta à fila sozinha, e dois processos nunca pegam a mesma linha.
//
// Só sai mensagem de bot **ligado e com envio autorizado**: se alguém desligar o bot enquanto a
// resposta espera, ela simplesmente não é entregue — a decisão mais nova é a que vale.
func (q *Queries) ReservarMensagensDeAtendimento(ctx context.Context, arg ReservarMensagensDeAtendimentoParams) ([]ReservarMensagensDeAtendimentoRow, error) {
	rows, err := q.db.Query(ctx, reservarMensagensDeAtendimento, arg.Slugs, arg.Limite)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ReservarMensagensDeAtendimentoRow
	for rows.Next() {
		var i ReservarMensagensDeAtendimentoRow
		if err := rows.Scan(
			&i.ID,
			&i.Texto,
			&i.Tentativas,
			&i.Telefone,
			&i.BotSlug,
			&i.ConversaID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const resumoAtendimento = `-- name: ResumoAtendimento :one

SELECT
    (SELECT count(*) FROM atendimento.bots b1)                                            AS bots,
    (SELECT count(*) FROM atendimento.bots b2 WHERE b2.ativo)                             AS bots_ativos,
    (SELECT count(*) FROM atendimento.conversas c1 WHERE c1.status = 'aberta')            AS conversas_abertas,
    (SELECT count(*) FROM atendimento.conversas c2 WHERE c2.iniciada_em >= $1)    AS conversas_hoje,
    (SELECT count(*) FROM atendimento.conversas c3
       WHERE c3.encerrada_em >= $2 AND c3.motivo = 'pediu_humano')                AS pediram_humano_mes,
    (SELECT count(*) FROM atendimento.conversas c4
       WHERE c4.encerrada_em >= $2 AND c4.motivo = 'concluido')                   AS concluidas_mes,
    (SELECT count(*) FROM atendimento.mensagens m1 WHERE m1.status = 'pendente')          AS fila_pendentes,
    (SELECT count(*) FROM atendimento.mensagens m2 WHERE m2.status = 'falhou')            AS fila_falharam,
    (SELECT count(*) FROM atendimento.mensagens m3
       WHERE m3.status = 'cancelada' AND m3.criada_em >= $2)                      AS canceladas_mes,
    (SELECT min(m4.proxima_tentativa_em) FROM atendimento.mensagens m4
       WHERE m4.status = 'pendente')                                                      AS proxima_da_fila,
    (SELECT count(*) FROM atendimento.coletas k1 WHERE k1.criado_em >= $2)        AS dados_mes,
    (SELECT coalesce(sum(c5.tokens_entrada + c5.tokens_saida), 0) FROM atendimento.conversas c5
       WHERE c5.ultima_em >= $2)::bigint                                          AS tokens_mes
`

type ResumoAtendimentoParams struct {
	DesdeHoje time.Time
	DesdeMes  *time.Time
}

type ResumoAtendimentoRow struct {
	Bots             int64
	BotsAtivos       int64
	ConversasAbertas int64
	ConversasHoje    int64
	PediramHumanoMes int64
	ConcluidasMes    int64
	FilaPendentes    int64
	FilaFalharam     int64
	CanceladasMes    int64
	ProximaDaFila    interface{}
	DadosMes         int64
	TokensMes        int64
}

// Etapa C (as telas). Consultas de LEITURA: o painel, a lista de conversas e a conversa aberta.
// Os períodos ("hoje", "no mês") vêm calculados da API no fuso de Brasília, como no resto da
// plataforma — o banco não decide onde o dia começa.
func (q *Queries) ResumoAtendimento(ctx context.Context, arg ResumoAtendimentoParams) (ResumoAtendimentoRow, error) {
	row := q.db.QueryRow(ctx, resumoAtendimento, arg.DesdeHoje, arg.DesdeMes)
	var i ResumoAtendimentoRow
	err := row.Scan(
		&i.Bots,
		&i.BotsAtivos,
		&i.ConversasAbertas,
		&i.ConversasHoje,
		&i.PediramHumanoMes,
		&i.ConcluidasMes,
		&i.FilaPendentes,
		&i.FilaFalharam,
		&i.CanceladasMes,
		&i.ProximaDaFila,
		&i.DadosMes,
		&i.TokensMes,
	)
	return i, err
}

const resumoDoFunil = `-- name: ResumoDoFunil :one
SELECT
    (SELECT count(*) FROM atendimento.leads WHERE funil_status = 'pendente')::bigint  AS pendentes,
    (SELECT count(*) FROM atendimento.leads WHERE funil_status = 'enviando')::bigint  AS enviando,
    (SELECT count(*) FROM atendimento.leads WHERE funil_status = 'erro')::bigint      AS com_erro,
    (SELECT count(*) FROM atendimento.leads
       WHERE funil_status = 'enviado' AND funil_enviado_em >= date_trunc('month', now()))::bigint AS enviados_mes,
    coalesce((SELECT l.funil_erro FROM atendimento.leads l
       WHERE l.funil_status = 'erro' ORDER BY l.id DESC LIMIT 1), '')::text           AS ultimo_erro
`

